using Autodesk.Revit.ApplicationServices;using Autodesk.Revit.DB;using SAUDICO.Federate.Shared;namespace SAUDICO.Federate.Core;public static class Detector{public static ModelKind Get(string p){using var i=BasicFileInfo.Extract(p);return !i.IsWorkshared?ModelKind.Local:i.IsCentral?ModelKind.Central:ModelKind.WorksharedLocal;}}public static class Opener{public static Document Open(Job j,Application a){var o=new OpenOptions();if(j.Kind==ModelKind.Central)o.DetachFromCentralOption=DetachFromCentralOption.DetachAndPreserveWorksets;if(j.Kind!=ModelKind.Local)o.SetOpenWorksetsConfiguration(new WorksetConfiguration(WorksetConfigurationOption.OpenAllWorksets));return a.OpenDocumentFile(ModelPathUtils.ConvertUserVisiblePathToModelPath(j.Source),o);}}